            new() { Id = 6, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Tue/Thu 9:00-10:15 AM + Fri Lab 2:00-4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with research interests in condensed matter.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 7, CourseCode = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with research interests in condensed matter.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 8, CourseCode = "ENG101", Title = "Composition and Rhetoric", Description = "Develop critical writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Mon/Wed 11:00 AM-12:15 PM", InstructorName = "Prof. Lisa Martinez", InstructorBio = "Prof. Martinez is a published author and has taught writing at the university level for over 20 years.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
